    "components.calendarsyncsettings.5b156f4dffc5": "确定删除系统日历里的「OneTHU 日程」日历？\n\n其中由 OneTHU 写入的全部事件将被移除；应用内的日程与云同步不受影响。",
    "components.calendarsyncsettings.5dec8ac021d7": "日程云同步（清华邮箱日历）",
    "components.calendarsyncsettings.5e9e9ab95a7b": "删除失败：{value}",
    "components.calendarsyncsettings.65dcde5641da": "连接成功，发现日历：{value}。",
    "components.calendarsyncsettings.6db47a772acc": "把课表与日程写入系统日历里的专属日历「OneTHU 日程」（不影响你已有的日历）。开启后自动更新课表、未提交作业与日程；课程与考试提前 15 分钟提醒，作业按提醒设置提前。macOS 日历可能随系统账户同步到其他设备。旧版本的同名日历请核对后自行清理。{value}",
    "components.calendarsyncsettings.8282a625a7e6": "已同步：写入 {added} 条（清理旧 {removed} 条）。",
    "components.calendarsyncsettings.9776893d3c55": "开启失败：{value}",
    "components.calendarsyncsettings.9e40f65d2856": "日历「OneTHU 日程」· 上次同步 {value} · {lastCount} 条。课表、未提交作业与日程变化后会自动更新。课程提前 15 分钟提醒，作业按提醒设置提前。{value2}{value3}",
    "components.calendarsyncsettings.a0813c42f2ad": "本平台不支持直写系统日历；可在「日程」页导出 .ics 再导入。",
    "components.calendarsyncsettings.a1fe9e82901d": "用清华邮箱的日历服务在多台设备间同步手动日程——OneTHU 里添加的日程会出现在系统日历 / 其他设备（添加同一账号）。 授权码获取：网页版邮箱（mails.tsinghua.edu.cn）→ 设置 → 客户端专用密码。{value}",
    "components.calendarsyncsettings.a7ec7c813f57": "清除系统日历",
    "components.calendarsyncsettings.a8d9c61f394a": "连接失败：{value}",
    "components.calendarsyncsettings.c4d0edd8c65a": "开启中…",
    "components.calendarsyncsettings.e50242f6c79b": "在 iPhone / iPad 上查看日程（可选）\n\n手机上没有 OneTHU 也没关系：日程已在你清华邮箱的云端日历里，在 iPhone/iPad 上添加同一邮箱即可看到：\n· 设置 → 日历 → 账户 → 添加账户 → 其他 → CalDAV 账户\n· 服务器地址：https://mails.tsinghua.edu.cn/coremail/dav/users/你的邮箱/\n· 用户名：完整邮箱；密码：客户端专用密码（与本页一致）\n\n本机不需要此设置——用下方「系统日历同步」一键开启即可，应用直接写系统日历。",
