    "components.onboardingtourparticles.e8898c88f026": "小组件",
    "components.onboardingtourv3.0195603ee49e": "OnePage：你的一页",
    "components.onboardingtourv3.06d3cfb40d27": "自带一块可以自由摆组件的白板页。",
    "components.onboardingtourv3.0afabdd4308c": "两条路就够：去搜索，去市场。",
    "components.onboardingtourv3.0b3cb95bce97": "大时间与一级功能区是骨架；其余组件随你摆。",
    "components.onboardingtourv3.0ca382e2edca": "底栏常驻：左「标签页」，中「搜索或问小OH」，右「OneGO!」。",
    "components.onboardingtourv3.16db14984ce5": "右键标签可复制、关闭，或一星收进 OnePage。",
    "components.onboardingtourv3.1878863a8e7b": "双击空白就地建便笺；画笔恒在最高层，可撤销清空。",
    "components.onboardingtourv3.1f5a2b96e178": "完成标记：此后不再自动出现",
    "components.onboardingtourv3.23f450edd90e": "设置里可定默认样式；竖栏底部按钮可切「窄」。",
    "components.onboardingtourv3.280832e11f57": "标签页与工作区",
    "components.onboardingtourv3.281c7d16e5bd": "右上角 × 只关闭这一次，下次启动还会出现。",
    "components.onboardingtourv3.285daf1ff2f1": "关闭本次导览",
    "components.onboardingtourv3.290f85ad4f6a": "右键空白（落点跟指针）或右侧 ＋：添加组件。",
    "components.onboardingtourv3.2b6332b718e8": "「安装插件」支持仓库直装与市场一键安装。",
    "components.onboardingtourv3.2cbb006447b1": "检索同源：面板搜得到的，页面里也搜得到。",
    "components.onboardingtourv3.2f8345141c89": "清华园随身工具箱。",
    "components.onboardingtourv3.30633ea11f9b": "命令面板（Ctrl+K）里也能直达你的白板。",
    "components.onboardingtourv3.3313a0968f97": "底栏「标签页」「OneGO!」抽屉里同样能看到工作区面板。",
    "components.onboardingtourv3.35915ce8d259": "回到导览",
    "components.onboardingtourv3.4ff4a0dbc4ef": "每步都可跳过；想重温，设置页右上角有「导览」。",
    "components.onboardingtourv3.5021907844de": "插件也有两下：给个仓库地址可当场安装。",
    "components.onboardingtourv3.514adbf12726": "在对话里说，它就动手。",
    "components.onboardingtourv3.5f0c74b96547": "一句话让 OH 建工具、跑流程、画组件、换主题、加手机小组件。",
    "components.onboardingtourv3.62a2fe77cea8": "底部中央胶囊「搜索或问小OH」：点开打字即搜。",
    "components.onboardingtourv3.67ab2cc6012c": "工具箱自己会长：说到哪，就长到哪。",
    "components.onboardingtourv3.6d3d4feb0c1a": "窄栏悬停在栏上即展开，移开即收。",
    "components.onboardingtourv3.715ee9dc842f": "开始使用",
    "components.onboardingtourv3.768ddf66b868": "页面都住在标签页里；拖一拖，就长成工作区。",
    "components.onboardingtourv3.794833cba26d": "横竖两副骨架",
    "components.onboardingtourv3.7c2809268e55": "OH：说一句，长一样本领",
    "components.onboardingtourv3.8a12026f5cee": "装插件、找一切",
    "components.onboardingtourv3.8f2ad7768678": "横版：标签在顶部一排；竖版：标签在左侧一列。",
    "components.onboardingtourv3.925a3ec4a592": "组件按住即拖，四角把手缩放，组件之间可以叠盖。",
    "components.onboardingtourv3.9552fe3bd366": "第 ",
    "components.onboardingtourv3.958b344e82b3": "OneTHU 桌面导览",
    "components.onboardingtourv3.99ffd3d1a875": "选中即浮出小工具条：置顶、透明度四档、删除。",
    "components.onboardingtourv3.a2d3a4eeefd7": "不再显示",
    "components.onboardingtourv3.a2de4ccdce72": "底栏「标签页」抽屉里有横版／竖版切换。",
    "components.onboardingtourv3.aa01e1d7252b": "本地插件能发布上 GitHub，并向市场提交收录。",
    "components.onboardingtourv3.acfc4e74a650": "下一步",
    "components.onboardingtourv3.b9f53c665e03": "顶部一排是标签页；换到竖版时在左侧栏。",
    "components.onboardingtourv3.bcd7acd491b0": "卡片让开，你动手；点胶囊回来继续",
    "components.onboardingtourv3.c0536a13ccc3": "把一张标签拖到另一张上，停 0.6 秒出灰框，松手合并。",
    "components.onboardingtourv3.c071633e0902": "标签页右键「一星」：把内容收成一块 OnePage。",
    "components.onboardingtourv3.c57439b82df9": "七步一分钟，看完桌面端的主干。",
    "components.onboardingtourv3.c575f6222266": "骨架不动：右键大时间或功能区可调透明度（四档）。",
    "components.onboardingtourv3.cb17e22bf3f0": "OneGO! 里还有 OneFlow：在 OH 对话里说「创建一个流程」。",
    "components.onboardingtourv3.d45c9dc68d4b": "演练中：把一张标签拖到另一张上，灰框出现就松手",
    "components.onboardingtourv3.d6a2506f30a7": "首页是一张自由白板",
    "components.onboardingtourv3.d750e7aaed28": "工作区底板就在标签栏上：右键可解散（标签保留）或删除。",
    "components.onboardingtourv3.da336fdc0dbd": "上一步",
    "components.onboardingtourv3.dc819c398a78": "底栏「OneGO!」→ 我的 OnePage：起名后点「新建」。",
    "components.onboardingtourv3.dd3208ca2917": "欢迎使用 OneTHU",
    "components.onboardingtourv3.dde91a15ff1f": "标签栏横竖随时切，窄一点也站得住。",
    "components.onboardingtourv3.e010e3f578cc": " 步",
    "components.onboardingtourv3.e18fe8598d89": "电脑可直接拖放；手机先点「编辑白板」，完成后点「完成编辑」。",
    "components.onboardingtourv3.edaec615b68d": "拖拽演练",
    "components.onboardingtourv3.f3ff6e20abc7": "任何页面按 Ctrl+K：输入即搜，回车直达。",
    "components.onboardingtourv3.f73a8a19c591": "设置 → 插件：「我的插件 / 插件市场」两个视图随时切。",
    "components.onboardingtourv3.f8d9c42c331f": "自己拖一次",
    "components.onboardingtourv3.fd73c2773154": " 步，共 ",
    "components.onboardingtourv3.fded5e53272d": "新建即得白板页，与首页同一套手势，摆什么都行。",
