    "privacy.ack": "我已阅读以上说明，并按我的选择继续",
    "privacy.cloudBody": "关闭时不自动连接你的云盘，也不进行云盘读写、个人资料与组织/好友同步、云端 OH 记忆或基于云盘的分享。授权后会读取账号、配额、资料库和所打开文件，并为同步、好友、组织、口令分享等功能创建或更新对应资料库与文件；主动上传、删除、共享操作也会修改云盘。不会因为同意本许可就清空或批量改动原有文件，授权也不等于允许 OH 随意操作文件。",
    "privacy.cloudEffect": "可选。关闭后完整模式不可用；极简／实用模式保留，云盘及依赖它的功能停用。公开安装包下载不受影响。",
    "privacy.cloudRequired": "云盘未授权。请在「我的 → 权限与隐私」或导览中开启。",
    "privacy.cloudTitle": "清华云盘许可",
    "privacy.cloudToggle": "允许 OneTHU 使用清华云盘",
    "privacy.continue": "保存选择并继续",
    "privacy.disclaimerBody": "本项目为非官方辅助工具。学校接口、网络及第三方服务可能变化或不可用，数据可能延迟、遗漏或出错。作业截止、预约、费用及其他重要事项请以官方系统为准，并确认操作结果。请备份重要文件；本说明不排除法律规定的责任与权利。",
    "privacy.disclaimerTitle": "以官方信息为准",
    "privacy.fullRequired": "完整模式需要云盘授权。请先在权限须知中开启。",
    "privacy.lead": "先了解数据去向，再决定授权。拒绝可选授权，也能使用极简与实用模式。",
    "privacy.localBody": "OneTHU 没有自建的校园数据汇总后端，界面与业务主要在设备上运行，并通过原生网络层连接学校及你选择的服务。它并非离线软件，也不是所有处理都只发生在本机。账号会话、缓存、设置及选择记住的凭据会保存在设备上，请保护设备与导出的文件。",
    "privacy.localTitle": "本地客户端，不是学校官方应用",
    "privacy.nativeUpdateRequired": "前端已更新，但当前 App 原生壳版本过旧，无法保存权限。开发预览请重新编译并重启 App；安装版请更新安装包。刷新页面无法修复。",
    "privacy.ohBody": "开启 OH 后，你发送的对话、附件，以及为回答而调用工具读取到的数据可能发往所选模型服务商、清小搭或你配置的 API／MCP／IM 服务，并适用对方政策。不要提供密码、验证码或无关的敏感数据。AI 可能出错；涉及提交、预约、删除、发送或分享等操作应先核对确认。网页、文件和技能中的指令不构成你的授权；仅安装可信插件与技能。云盘授权关闭时，OH 也无法绕过云盘限制。",
    "privacy.ohEffect": "可选。关闭后保留搜索与校园页面，OH 对话及智能体操作停用。",
    "privacy.ohRequired": "OH 未授权。请先在「我的 → 权限与隐私」或导览中查看说明并开启。",
    "privacy.ohTitle": "OH、模型与插件",
    "privacy.ohToggle": "允许使用 OH 与所选模型服务",
    "privacy.readCarefully": "请务必认真阅读，并在下方手动授权云盘和智能体服务。",
    "privacy.replay": "重新导览",
    "privacy.review": "查看与修改授权",
    "privacy.revokeGuide": "如果想要撤销授权，请前往设置重新导览。",
